 function makeDetailedPiece(name){const g=new T.Group();let matched=true;switch(name){case 'Gabinete y botonera':buildControlCabinet20(g);break;case 'Mando de transferencia':buildTransferCabinet20(g);break;case 'Tanque y filtro':hdFuelTank(g);break;case 'Retorno, válvula de corte y separador':if(['ng','lpg'].includes(activeFuel()))matched=false;else hdSeparator(g);break;case 'Bridas, apoyos y caja de bornes':coherentAlternatorMount(g);break;case 'Turbocompresor y conexión de admisión':coherentTurbo(g);break;case 'Bloque y cárter':hdBlock(g);break;case 'Inyectores y culata':case 'Bujías y culata':hdHead(g);break;case 'Distribución: árbol de levas, balancines y válvulas':hdValveTrain(g);break;case 'Ventilador':hdFan(g);break;case 'Admisión y filtro de aire':hdIntake(g);break;case 'Filtros de aceite y conductos':hdOilFilters(g);break;case 'Motor de arranque':hdStarter(g);break;case 'Batería de arranque':hdBattery(g);break;case 'Radiador y mangueras':hdRadiator(g);break;case 'Pistones y bielas':hdPistons(g);break;case 'Cigüeñal y volante':hdCrankshaft(g);break;case 'Rotor y bobinado':hdRotor(g);break;case 'Núcleo laminado y cabezas de bobina':hdStator(g);break;case 'Estator y carcasa':hdHousing(g);break;case 'Elemento filtrante':matched=hdPaperFilter(g);break;case 'Placa electrónica y procesador':hdBoard(g);break;case 'Tarjeta de mando y bornes de señal':hdBoard(g,[3.65,1.05,.10]);break;case 'Placas y separadores de batería':hdBatteryPlates(g);break;case 'Inducido y eje del arrancador':hdArmature(g);break;case 'Cámaras y tubo perforado':hdSilencer(g);break;default:matched=EDU_PARTS.some(p=>p[1]===name);if(matched)eduBuild(name,g);}return matched?g:null;}

 function styleClone(c){c.traverse(o=>{o.visible=true;if(!o.isMesh)return;o.userData.ppOwner=c.userData.presentationName;o.userData.ppKey=c.userData.presentationKey;o.material=o.material.clone();o.castShadow=o.receiveShadow=true;o.material.envMapIntensity=1.1;SurfaceRealism.finishMesh(o,c.userData,true);o.material.opacity=o.material.userData.fuelBowl?.42:o.material.userData.glass20?.14:1;o.material.transparent=o.material.userData.fuelBowl||o.material.userData.glass20||!!o.material.map&&!o.material.map.userData.sharedFinish&&!o.material.isMeshStandardMaterial;o.material.depthWrite=!o.material.transparent;o.material.emissive?.set('#000');});}
 function setTags(items){$('ppLeaders').replaceChildren();visual.querySelectorAll('.pp-tag').forEach(e=>e.remove());tagItems=[];items.forEach((it,i)=>{const b=document.createElement('button');b.className='pp-tag';b.innerHTML='<b>'+it.number+'</b><span></span>';b.lastElementChild.textContent=it.name;b.onclick=it.action;visual.append(b);const line=document.createElementNS('http://www.w3.org/2000/svg','line'),dot=document.createElementNS('http://www.w3.org/2000/svg','circle');dot.setAttribute('r','3');$('ppLeaders').append(line,dot);tagItems.push({b,line,dot,key:it.key,obj:it.obj,name:it.name});});}
 function generalTags(){setTags(order.map((key,i)=>({key,number:String(i+1).padStart(2,'0'),name:names[key],action:()=>choose(i)})));}
 function layoutInspection(){inspectionItems=clones.filter(c=>c.userData.presentationKey===order[selected]);const occupied=[];for(const [i,c]of inspectionItems.entries()){c.position.set(0,0,0);c.visible=true;c.updateMatrixWorld(true);const bounds=boundsOf(c);const dir=new T.Vector3(...(c.userData.offset||[.6,.7,1]));if(dir.length()<.15)dir.set(i%2?1:-1,.7,1);dir.normalize();let offset=new T.Vector3();if(i){for(let step=1;step<=100;step++){offset.copy(dir).multiplyScalar(step*.25);const candidate=bounds.clone().translate(offset).expandByScalar(.10);if(!occupied.some(box=>box.intersectsBox(candidate)))break;}}c.userData.exploded=offset.clone();occupied.push(bounds.clone().translate(offset).expandByScalar(.10));}const union=new T.Box3();occupied.forEach(b=>union.union(b));const lift=Math.max(0,.12-union.min.y);inspectionItems.forEach(c=>c.userData.exploded.y+=lift);}
 function applySpread(){for(const c of clones){c.visible=inspectMode?c.userData.presentationKey===order[selected]&&(!subpiece||c.userData.presentationName===subpiece):!c.userData.synthetic&&(!(c.userData.canopy||c.userData.key==='enclosure'&&c.userData.shell)||coverInstalled);c.position.copy(inspectMode?(c.userData.exploded||new T.Vector3()).clone().multiplyScalar(spread):new T.Vector3());}if(r)r.shadowMap.needsUpdate=true;controls.hidden=!inspectMode;$('ppSpread').value=spread*100;if(baseFloor)baseFloor.visible=!inspectMode;if(contactFloor)contactFloor.visible=!inspectMode;const covered=coverInstalled&&!inspectMode;$('ppCover').textContent=covered?'Retirar cubierta':'Colocar cubierta';$('ppCover').setAttribute('aria-pressed',String(covered));$('ppCoverStatus').hidden=inspectMode;$('ppCoverStatus').textContent=inspectMode?'Despiece del sistema · Selecciona una subpieza para verla por separado.':covered?'Cubierta colocada · Retírala para ver la anatomía del equipo.':'Cubierta retirada · Gira el equipo o selecciona un sistema para ver su despiece.';}
 function fittedView(object){assembly.updateMatrixWorld(true);const b=new T.Box3();if(object)b.copy(boundsOf(object));else inspectionItems.forEach(c=>b.union(boundsOf(c)));const center=b.getCenter(new T.Vector3()),size=b.getSize(new T.Vector3());const aspect=Math.max(.4,visual.clientWidth/visual.clientHeight);const distance=Math.max(.8,size.length()/(2*Math.tan(cam.fov*Math.PI/360)*Math.min(1,aspect))*(object&&aspect>1?.96:1.22));return {center,distance};}
 function moveView(to,animate=true){cancelAnimationFrame(animationId);const from=viewTarget.clone(),initial=viewDistance,started=performance.now();if(!animate||matchMedia('(prefers-reduced-motion: reduce)').matches){viewTarget.copy(to.center);viewDistance=to.distance;draw();return;}function step(now){if(!dialog.open)return;const u=Math.min(1,(now-started)/550),t=u*u*(3-2*u);viewTarget.lerpVectors(from,to.center,t);viewDistance=initial+(to.distance-initial)*t;draw();if(u<1)animationId=requestAnimationFrame(step);}animationId=requestAnimationFrame(step);}
 function inspectSystem(){inspectMode=true;coverInstalled=false;subpiece=null;spread=1;zoom=1;layoutInspection();applySpread();setTags(inspectionItems.map((c,i)=>({key:order[selected],obj:c,number:(selected+1)+'.'+(i+1),name:c.userData.presentationName,action:()=>selectSubpiece(c.userData.presentationName)})));moveView(fittedView());}
 function selectSubpiece(name){if(!inspectMode)inspectSystem();subpiece=name;const c=clones.find(c=>c.userData.presentationName===name);if(!c)return;applySpread();$('ppComponentInfo').hidden=false;$('ppComponentInfo').textContent=c.userData.explain||pieces.find(p=>p.userData.name===name)?.userData.explain||'';$('ppComponents').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.piece===name)));zoom=1;moveView(fittedView(c));}
 function wholePlant(){cancelAnimationFrame(animationId);inspectMode=false;subpiece=null;spread=1;zoom=1;viewTarget.set(.4,1.4,0);viewDistance=13;applySpread();generalTags();draw();}
 controls.querySelector('#ppSpread').oninput=()=>{spread=+$('ppSpread').value/100;applySpread();moveView(fittedView(subpiece?clones.find(c=>c.userData.presentationName===subpiece):null),false);};$('ppAssemble').onclick=()=>{spread=0;subpiece=null;applySpread();moveView(fittedView());};$('ppExplode').onclick=()=>{spread=1;subpiece=null;applySpread();moveView(fittedView());};$('ppWhole').onclick=wholePlant;

 function setRotation(enabled){autoRotating=!!enabled;rotationLast=0;const button=$('ppRotation');button.textContent=autoRotating?'Pausar rotación':'Reanudar rotación';button.setAttribute('aria-pressed',String(autoRotating));if((autoRotating||window.PresentationTour45?.state().active)&&dialog.open&&!rotationId)rotationId=requestAnimationFrame(rotationFrame);}
 function rotationFrame(now){rotationId=0;if(!dialog.open)return;const dt=rotationLast?Math.min(.12,Math.max(0,(now-rotationLast)/1000)):0;rotationLast=now;window.PresentationTour45?.frame(dt);if(!dialog.open)return;if(autoRotating&&!dragging&&!document.hidden){yaw=(yaw+dt*Math.PI/30)%(Math.PI*2);if(now-rotationDrawLast>=1000/30){rotationDrawLast=now;draw();}}if(autoRotating||window.PresentationTour45?.state().active)rotationId=requestAnimationFrame(rotationFrame);}
 $('ppRotation').onclick=()=>{if(autoRotating){cancelAnimationFrame(rotationId);rotationId=0;}setRotation(!autoRotating);};
