 const launch=document.createElement('dialog');launch.id='gameLaunch';launch.setAttribute('aria-labelledby','gameLaunchTitle');launch.innerHTML=`<div class="g-launch-wrap"><div class="g-launch-top"><div class="g-brand"><span class="g-brand-mark">G / 01</span>EMERGENCIA · SIMULADOR 3D</div><span class="g-launch-meta">CENTRO DE ENTRENAMIENTO / D49.1</span></div><div class="g-launch-main"><div class="g-launch-intro"><div class="g-eyebrow">OPERACIÓN · EXPLORACIÓN · APRENDIZAJE</div><h2 id="gameLaunchTitle">La red falla.<br><em>Tú tomas<br>el control.</em></h2><p>Explora la planta, conoce cada componente y observa la respuesta del sistema ante una interrupción del suministro.</p><div class="g-entry-actions"><button id="gameEnter">Explorar instalación <span>↗</span></button><button id="gameTraining">01 &nbsp; Elegir una misión</button><button id="gameAnatomy">02 &nbsp; Anatomía de la planta</button></div><button id="gameContinue" hidden>Continuar sesión →</button><div class="g-launch-note">MODELO 3D INTERACTIVO · CONTROLES DE CÁMARA LIBRES</div></div><div class="g-launch-right"><div id="gameRoutePane"><div class="g-launch-right-head"><strong>Dos fuentes. Una instalación.</strong><span class="g-eyebrow">G-01 / MT</span></div><svg viewBox="0 0 340 290" role="img" aria-label="Ruta funcional: red por QN o generador por Q0, elevador y QG; barra común, transformador reductor y fábrica"><path class="g-route-path" d="M70 68V156 M270 68V156 M70 180H270 M70 168V180 M270 168V180 M170 180V221 M170 247V270"/><rect id="gameRouteGrid" x="16" y="20" width="108" height="48" rx="7" class="g-route-node g-route-active"/><text x="70" y="40" text-anchor="middle" class="g-route-label">RED NORMAL</text><text x="70" y="57" text-anchor="middle" class="g-route-value">13.8 kV</text><rect id="gameRouteGen" x="216" y="20" width="108" height="48" rx="7" class="g-route-node"/><text x="270" y="40" text-anchor="middle" class="g-route-label">GRUPO G-01</text><text x="270" y="57" text-anchor="middle" class="g-route-value">480 V</text><text x="285" y="92" class="g-route-label">Q0</text><rect x="248" y="104" width="44" height="25" rx="3" class="g-route-node"/><text x="270" y="121" text-anchor="middle" class="g-route-label">TE ↑</text><rect x="64" y="156" width="12" height="12" class="g-route-node"/><rect x="264" y="156" width="12" height="12" class="g-route-node"/><text x="88" y="166" class="g-route-label">QN</text><text x="288" y="166" class="g-route-label">QG</text><circle cx="170" cy="180" r="3" fill="#a9d7b9"/><text x="170" y="203" text-anchor="middle" class="g-route-label">BARRA 13.8 kV · QS</text><rect x="144" y="221" width="52" height="26" rx="3" class="g-route-node"/><text x="170" y="239" text-anchor="middle" class="g-route-label">TP ↓</text><text x="170" y="287" text-anchor="middle" class="g-route-label">FÁBRICA / CCM · 480 V</text></svg><div class="g-route-state" id="gameRouteState"></div></div><div id="gameMissionsPane" hidden><div class="g-launch-right-head"><strong>Elige tu próxima misión</strong><span class="g-eyebrow">03 PRUEBAS</span></div><button class="g-mission-choice" data-mission="transfer"><span class="g-mission-num">01</span><span><b>Recupera el suministro</b><small>Falla de red, arranque del grupo y transferencia de la carga.</small></span><span>↗</span></button><button class="g-mission-choice" data-mission="load"><span class="g-mission-num">02</span><span><b>Responde a la demanda</b><small>Escalones de carga de 25, 50, 75 y 100%. Observa tensión y frecuencia.</small></span><span>↗</span></button><button class="g-mission-choice" data-mission="starter"><span class="g-mission-num">03</span><span><b>Verifica el bloqueo</b><small>Falla de arranque: observa los tres intentos y el aviso de protección.</small></span><span>↗</span></button><button id="gameBackRoute" class="g-back-route">← Volver a la instalación</button><p class="g-launch-note">Al iniciar una prueba se reinicia el escenario eléctrico.</p></div></div></div><div class="g-launch-foot"><span>SUBESTACIÓN · PLANTA DE EMERGENCIA · FÁBRICA</span><span>SIMULACIÓN EDUCATIVA / TIEMPOS ABREVIADOS</span></div></div>`;document.body.append(launch);
 const help=document.createElement('dialog');help.id='gameHelp';help.setAttribute('aria-labelledby','gameHelpTitle');help.innerHTML='<div class="g-eyebrow">GUÍA DE OPERACIÓN</div><h2 id="gameHelpTitle">Tus controles</h2><p>El puntero controla la cámara. Los atajos operan la simulación cuando no hay un diálogo o campo de texto activo.</p><dl><dt>Arrastrar</dt><dd>Desplazar la cámara</dd><dt>Shift + arrastrar</dt><dd>Girar la cámara</dd><dt>Rueda</dt><dd>Acercar o alejar</dd><dt>1–6</dt><dd>Ir a una de las seis zonas</dd><dt>E / X</dt><dd>Arrancar / detener el grupo</dd><dt>G</dt><dd>Cortar o restaurar la red</dd><dt>Espacio</dt><dd>Pausar o continuar</dd><dt>R</dt><dd>Reiniciar el escenario eléctrico</dd><dt>M / H</dt><dd>Menú de misiones / esta ayuda</dd></dl><button id="gameHelpClose">Volver a la simulación</button>';document.body.append(help);
 let hasEntered=false,menuRestorePause=false,missionSignature='';
 function showMenu(missions=false){if(launch.open){showMissions(missions);return;}menuRestorePause=paused;paused=true;window.gameMenuActive=true;showMissions(missions);$('gameContinue').hidden=!hasEntered;launch.showModal();if(missions)$('gameMissionsPane').scrollIntoView({block:'center'});refresh();}
 function showMissions(on){$('gameRoutePane').hidden=on;$('gameMissionsPane').hidden=!on;if(on&&launch.open)$('gameMissionsPane').scrollIntoView({block:'center'});}
 function restoreMenu(){if(launch.open||!window.gameMenuActive)return;hasEntered=true;window.gameMenuActive=false;paused=menuRestorePause;last=performance.now();refresh();renderUI();}
 launch.addEventListener('close',restoreMenu);launch.addEventListener('cancel',event=>{event.preventDefault();if(hasEntered)leaveMenu();});
 function leaveMenu(){if(launch.open)launch.close();restoreMenu();hasEntered=true;}
 menuButton.onclick=()=>showMenu();$('gameChooseMission').onclick=()=>showMenu(true);$('gameTraining').onclick=()=>showMissions(true);$('gameBackRoute').onclick=()=>showMissions(false);$('gameContinue').onclick=leaveMenu;
 $('gameEnter').onclick=()=>{const first=!hasEntered;leaveMenu();if(first)go('general');toast('Exploración libre · selecciona una zona o gira la cámara');};
 $('gameAnatomy').onclick=()=>{leaveMenu();$('openPlantPresentation').click();};
 launch.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{leaveMenu();go('emergency');UnidadVII.test(b.dataset.mission);refresh();toast('Misión iniciada · observa la secuencia en tiempo simulado');});
 $('gameControlsHelp').onclick=()=>help.showModal();$('gameHelpClose').onclick=()=>help.close();
 const missions={transfer:{name:'Recupera el suministro',description:'Observa el arranque y la transferencia automática a la fuente de respaldo.',steps:['Interrumpir la red','Grupo disponible','Carga alimentada por planta']},load:{name:'Responde a la demanda',description:'Observa la recuperación de tensión y frecuencia en cada escalón de carga.',steps:['Transferir al grupo','Alcanzar el cuarto escalón','Finalizar el ensayo']},starter:{name:'Verifica el bloqueo',description:'Observa cómo responde el controlador cuando el grupo no puede arrancar.',steps:['Introducir falla de arranque','Completar tres intentos','Verificar bloqueo y alarma']}};
 function refresh(){if(!$('gameLive'))return;const frozen=paused||window.plantPresentationActive;$('gameLive').textContent=frozen?'EN PAUSA':'EN SIMULACIÓN';$('gameLive').dataset.paused=String(!!frozen);$('gameRouteGrid').classList.toggle('g-route-active',s.source==='grid');$('gameRouteGen').classList.toggle('g-route-active',s.source==='gen');const route=$('gameRouteState');route.textContent=s.source==='grid'?'Servicio normal: la red alimenta la carga.':s.source==='gen'?'Respaldo activo: el grupo alimenta la carga.':'Sin suministro a la carga: observa la respuesta del sistema.';const test=eduTest,def=test&&missions[test.kind];const done=test?(test.kind==='transfer'?[true,test.ready!=null,test.transfer!=null]:test.kind==='load'?[test.transfer!=null,test.step===3,!!test.done]:[true,s.attempts>=3,!!test.done]):[];const signature=JSON.stringify([test?.kind,test?.start,done,test?.done,test?.result]);if(signature!==missionSignature){missionSignature=signature;$('gameMissionTitle').textContent=def?def.name:'Exploración libre';$('gameMissionDescription').textContent=def?def.description:'Conoce la instalación o elige una prueba de respuesta del grupo electrógeno.';const steps=$('gameSteps');steps.replaceChildren();if(def)def.steps.forEach((text,i)=>{const li=document.createElement('li');li.textContent=text;li.dataset.done=String(done[i]);steps.append(li);});$('gameMissionBar').style.width=def?(done.filter(Boolean).length/3*100)+'%':'0%';$('gameResult').hidden=!test?.done;$('gameResult').textContent=test?.result||'';}
 $('gameMissionTime').textContent=test?(test.done?'PRUEBA FINALIZADA':'TIEMPO '+Math.max(0,s.t-test.start).toFixed(1)+' s'):'NAVEGACIÓN LIBRE · 6 ZONAS';
 for(const id of ['grid','pause']){const b=dock.querySelector('[data-act="'+id+'"]');b.querySelector('.g-button-label>span').textContent=id==='grid'?(s.grid?'Cortar red':'Restaurar red'):(frozen?'Continuar':'Pausar');b.title=id==='grid'?(s.grid?'Cortar red · G':'Restaurar red · G'):(frozen?'Continuar · ESPACIO':'Pausar · ESPACIO');b.setAttribute('aria-pressed',String(id==='pause'?!!frozen:!s.grid));}
 const active=document.querySelector('#viewbar [data-nav].active')?.dataset.nav;map.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.zone===active)));}
 const priorUI=renderUI;renderUI=function(...args){priorUI(...args);refresh();};
 document.querySelectorAll('#viewbar [data-nav]').forEach(b=>b.addEventListener('click',()=>{refresh();toast('Cámara · '+b.textContent);}));
 document.addEventListener('keydown',event=>{if(event.repeat||event.ctrlKey||event.altKey||event.metaKey||event.target.closest('input,select,textarea,[contenteditable=true]')||document.querySelector('dialog[open]'))return;const key=event.key.toLowerCase();const ids={e:'start',x:'stop',g:'grid',' ':'pause',r:'reset'};if(ids[key]){event.preventDefault();$(ids[key]).click();refresh();}else if(/^[1-6]$/.test(key)){event.preventDefault();document.querySelectorAll('#viewbar [data-nav]')[+key-1]?.click();}else if(key==='m'){event.preventDefault();showMenu(true);}else if(key==='h'){event.preventDefault();help.showModal();}});
 window.GameInterface={openMenu:showMenu,closeMenu:leaveMenu,state:()=>({hasEntered,menuOpen:launch.open,menuPausesSimulation:!!window.gameMenuActive,mission:eduTest?.kind||null,paused}),refresh};
 showMenu();
